CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','editor','author','reader') NOT NULL DEFAULT 'reader', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS authors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL UNIQUE, display_name VARCHAR(120) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, bio TEXT NULL, avatar_media_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description TEXT NULL, position INT NOT NULL DEFAULT 0, INDEX(parent_id));
CREATE TABLE IF NOT EXISTS tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, disk VARCHAR(30) NOT NULL DEFAULT 'local', path VARCHAR(500) NOT NULL, mime_type VARCHAR(100) NOT NULL, bytes BIGINT UNSIGNED NOT NULL, width INT NULL, height INT NULL, alt_text VARCHAR(255) NULL, credit VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NOT NULL, hero_media_id BIGINT UNSIGNED NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(190) NOT NULL, excerpt TEXT NULL, body LONGTEXT NOT NULL, status ENUM('draft','review','scheduled','published','archived') NOT NULL DEFAULT 'draft', published_at DATETIME NULL, meta_title VARCHAR(255) NULL, meta_description VARCHAR(320) NULL, canonical_url VARCHAR(500) NULL, robots VARCHAR(100) NOT NULL DEFAULT 'index,follow', is_sponsored TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unique_category_slug(category_id, slug), INDEX(status, published_at), FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(author_id) REFERENCES authors(id));
CREATE TABLE IF NOT EXISTS article_tags (article_id BIGINT UNSIGNED NOT NULL, tag_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(article_id,tag_id), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, article_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, author_name VARCHAR(120) NULL, body TEXT NOT NULL, status ENUM('pending','approved','rejected','spam') NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, article_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, type VARCHAR(30) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(article_id, type));
CREATE TABLE IF NOT EXISTS bookmarks (user_id BIGINT UNSIGNED NOT NULL, article_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS newsletter_subscribers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, status ENUM('pending','active','unsubscribed') NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ad_slots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL, page_scope VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS advertisements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ad_slot_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, content_html TEXT NOT NULL, starts_at DATETIME NULL, ends_at DATETIME NULL, impressions BIGINT UNSIGNED NOT NULL DEFAULT 0, clicks BIGINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(ad_slot_id) REFERENCES ad_slots(id));
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(120) PRIMARY KEY, `value` JSON NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
